describe('WebSocket Connection Tests', () => {
    beforeEach(() => {
        cy.visit('/'); // Visit the application page
    });

    it('should update the UI in real-time when a message is received', () => {
        cy.window().then((win) => {
            const socket = new WebSocket('ws://localhost:8080');
            socket.onmessage = (event) => {
                const data = JSON.parse(event.data);
                win.document.querySelector('#message').innerText = data.message;
            };
            socket.onopen = () => {
                socket.send(JSON.stringify({ action: 'subscribe' }));
            };
        });

        cy.intercept('GET', '/api/messages', { fixture: 'messages.json' }).as('getMessages');
        cy.wait('@getMessages');

        cy.get('#message').should('have.text', 'Initial message');

        cy.wait(1000); // Wait for WebSocket message to be received
        cy.get('#message').should('have.text', 'Updated message');
    });

    it('should handle WebSocket connection errors gracefully', () => {
        cy.window().then((win) => {
            const socket = new WebSocket('ws://localhost:8080');
            socket.onerror = () => {
                win.document.querySelector('#error').innerText = 'WebSocket error occurred';
            };
            socket.onopen = () => {
                socket.close(); // Close immediately to trigger error
            };
        });

        cy.get('#error').should('have.text', 'WebSocket error occurred');
    });
});
